require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Dashboard';$event=active_event();$totals=$event?LeaderboardService::totals((int)$event['id']):[];$finalistCount=$event?(int)db()->query('SELECT COUNT(*) FROM finalists WHERE event_id='.(int)$event['id'])->fetchColumn():0;$recent=[];$chartLabels=[];$chartData=[];$top=[];if($event){$stmt=db()->prepare("SELECT vo.*,f.full_name finalist_name FROM vote_orders vo JOIN finalists f ON f.id=vo.finalist_id WHERE vo.event_id=? ORDER BY vo.id DESC LIMIT 8");$stmt->execute([$event['id']]);$recent=$stmt->fetchAll();$stmt=db()->prepare("SELECT DATE(created_at) d,SUM(amount_snapshot) total FROM vote_orders WHERE event_id=? AND payment_status='PAID' AND created_at>=DATE_SUB(CURDATE(),INTERVAL 13 DAY) GROUP BY DATE(created_at) ORDER BY d");$stmt->execute([$event['id']]);foreach($stmt->fetchAll() as $r){$chartLabels[]=date('d M',strtotime($r['d']));$chartData[]=(int)$r['total'];}$top=array_merge(LeaderboardService::rankings((int)$event['id'],'BUJANG',3,false),LeaderboardService::rankings((int)$event['id'],'DAYANG',3,false));usort($top,fn($a,$b)=>(int)$b['total_points']<=>(int)$a['total_points']);$top=array_slice($top,0,5);}require __DIR__.'/partials/header.php';
